  }
  #game-container {
    position: relative;
    box-shadow: 0 15px 40px rgba(0,0,0,0.8);
    border-radius: 10px;
    overflow: hidden;
    background: #3a2314;
  }
  canvas {
    display: block;
    cursor: crosshair;
  }
  #controls {
    margin-top: 20px;
    display: flex;
    gap: 20px;
    align-items: center;
  }
  button {
    padding: 10px 20px;
    font-size: 16px;
