    cursor: pointer;
    transition: background 0.2s;
  }
  button:hover {
    background: #388e3c;
  }
  #status {
    font-size: 16px;
    color: #aaa;
  }
  #instructions {
    max-width: 800px;
    text-align: center;
    margin-top: 15px;
    color: #ccc;
    line-height: 1.6;
    background: #2a2a2a;
    padding: 15px 20px;
    border-radius: 8px;
  }
  b { color: #fff; }
